  Visits = c(142, 96, 61, 48, 30)
)

p13 <- ggplot(tutoring_visits, aes(x = Reason, y = Visits)) +
  geom_col(
    width = 0.68, fill = book_palette[["blue"]],
    colour = BOOK_INK, linewidth = 0.35
  ) +
  geom_text(
    aes(label = Visits), vjust = -0.45, size = 3.4, colour = BOOK_INK
  ) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.12))) +
  labs(x = "Reason for visit", y = "Number of visits") +
