# ---- Figure 1.5: histogram with a normal curve -----------------------------

sleep_mean <- mean(sl$WeekdaySleep)
sleep_sd <- sd(sl$WeekdaySleep)

p15 <- ggplot(sl, aes(x = WeekdaySleep)) +
  geom_histogram(
    aes(y = after_stat(count)), binwidth = 1, boundary = 0,
    fill = book_palette[["sky_blue"]], colour = BOOK_INK, linewidth = 0.3
  ) +
  stat_function(
    aes(colour = "Normal curve"),
    fun = function(x) dnorm(x, sleep_mean, sleep_sd) * n_students,
    linewidth = 1, n = 300
  ) +
  scale_colour_manual(
    values = c("Normal curve" = book_palette[["vermillion"]]), name = NULL
  ) +
  scale_x_continuous(breaks = 3:11) +
  coord_cartesian(xlim = c(2.5, 11.5)) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.05))) +
  labs(x = "Weekday sleep (hours)", y = "Number of students") +
  book_theme()

save_book_fig(
  p15,
  chapter = 1, id = "1.5", type = "hist", slug = "sleep_normal_overlay",
  caption = "Weekday sleep hours with a fitted normal curve. The histogram is roughly symmetric and centered near 8 hours.",
  alt = paste(
    "Histogram of weekday sleep hours with a smooth bell-shaped normal curve",
    "overlaid. The histogram is roughly symmetric, peaks at 7 to 9 hours, and",
    "the curve follows the same shape."
  ),
  direct_labels = TRUE
)

