# ---- Figure 1.8: segmented bar chart ---------------------------------------

stress_alcohol <- sl %>%
  count(Stress, AlcoholUse) %>%
  group_by(Stress) %>%
  mutate(share = n / sum(n)) %>%
  ungroup()

p18 <- ggplot(stress_alcohol, aes(x = Stress, y = share, fill = AlcoholUse)) +
  geom_col(width = 0.62, colour = BOOK_INK, linewidth = 0.35) +
  geom_text(
    aes(label = ifelse(
      share < 0.10,
      paste0(AlcoholUse, " ", percent(share, accuracy = 1)),
      paste0(AlcoholUse, "\n", percent(share, accuracy = 1))
    )),
    position = position_stack(vjust = 0.5), size = 2.9, lineheight = 0.9,
    colour = contrast_text(alcohol_cols[as.character(stress_alcohol$AlcoholUse)])
  ) +
  scale_y_continuous(
    labels = percent_format(accuracy = 1), expand = expansion(mult = c(0, 0))
  ) +
  scale_fill_manual(values = alcohol_cols, name = "Alcohol use") +
  labs(x = "Stress level", y = "Share within stress group") +
  book_theme() +
  theme(panel.grid.major.x = element_blank())

save_book_fig(
  p18,
  chapter = 1, id = "1.8", type = "segmented", slug = "alcohol_by_stress",
  caption = "Alcohol use within each stress group. Each bar is scaled to 100%, so the actual group sizes are hidden.",
  alt = paste(
    "Segmented bar chart of alcohol use within stress groups. In the High",
    "stress group, Moderate drinkers are 41%, Light 36%, Abstain 14%, and",
    "Heavy 9%. In the Normal stress group, Moderate is 49%, Light 32%,",
    "Abstain 13%, and Heavy 6%."
  ),
  direct_labels = TRUE
)

# ---- Figure 1.9: mosaic plot ------------------------------------------------

stress_sizes <- sl %>%
  count(Stress) %>%
  mutate(
    width = n / sum(n),
    xmax = cumsum(width),
    xmin = c(0, head(xmax, -1))
  ) %>%
  select(Stress, width, xmin, xmax)

mosaic <- sl %>%
  count(Stress, AlcoholUse) %>%
  left_join(stress_sizes, by = "Stress") %>%
  group_by(Stress) %>%
  arrange(AlcoholUse, .by_group = TRUE) %>%
  mutate(
    share = n / sum(n),
    ymax = cumsum(share),
    ymin = c(0, head(ymax, -1))
  ) %>%
  ungroup() %>%
  mutate(
    xmid = (xmin + xmax) / 2,
    ymid = (ymin + ymax) / 2,
    label = ifelse(
      share < 0.10,
      paste0(AlcoholUse, " ", percent(share, accuracy = 1)),
      paste0(AlcoholUse, "\n", percent(share, accuracy = 1))
    ),
    text_colour = contrast_text(alcohol_cols[as.character(AlcoholUse)])
  )

p19 <- ggplot(mosaic) +
  geom_rect(
    aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, fill = AlcoholUse),
    colour = BOOK_INK, linewidth = 0.4
  ) +
  geom_text(
    aes(x = xmid, y = ymid, label = label, colour = text_colour),
    size = 2.7, lineheight = 0.9, show.legend = FALSE
  ) +
  scale_colour_identity() +
  scale_fill_manual(values = alcohol_cols, name = "Alcohol use") +
  scale_x_continuous(
    breaks = stress_sizes$xmin + stress_sizes$width / 2,
    labels = as.character(stress_sizes$Stress),
    expand = expansion(mult = c(0.01, 0.01))
  ) +
  scale_y_continuous(
    labels = percent_format(accuracy = 1),
    expand = expansion(mult = c(0.01, 0.01))
  ) +
  labs(x = "Stress level", y = "Share within stress group") +
  book_theme() +
  theme(panel.grid = element_blank())

save_book_fig(
  p19,
  chapter = 1, id = "1.9", type = "mosaic", slug = "stress_alcohol",
  caption = "Mosaic plot of stress level and alcohol use. Column width shows group size; block height shows the share within each group.",
  alt = paste(
    "Mosaic plot of stress level and alcohol use. The Normal stress column is",
    "much wider, showing 197 students versus 56 under High stress. Within each",
    "column, Moderate drinkers form the largest block; the Heavy block is 6%",
    "under Normal stress and 9% under High stress."
  ),
  match = "A mosaic plot of Stress and AlcoholUse",
  direct_labels = TRUE
)

